using System.Net.Http.Headers;
using System.Text;
using System.Text.Json;
using PetService.Core;
namespace PetService;
internal sealed class PrivateChatSession(Plugin plugin):IDisposable
{
 private readonly HttpClient http=new(new HttpClientHandler{AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(12)};
 private readonly CancellationTokenSource cancel=new();private Task<JsonElement>? work;private Action<JsonElement>? completed;private long nextPoll;private string password="",vaultKey="";private bool enrolled,loadingOlder,refreshFirst;private string pendingRoom="";private bool vaultSaved=true;
 internal bool Focused{get;set;}=true;
 internal bool Paused=>!Master&&(!plugin.IsPaired||!plugin.CharacterAllowed);
 internal ChatPreferences Preferences{get;private set;}=new();
 internal bool ConversationPaused(string id)=>Preferences.GlobalPaused||Preferences.Paused.Contains(id);
 internal void Preference(string? room=null,bool? muted=null,bool? paused=null,bool? global=null){Start("preferences",new{threadId=room,muted,paused,globalPaused=global},v=>{Preferences=v.Deserialize<ChatPreferences>(ServiceClient.Json)!;nextPoll=0;});}
 internal bool HasCredential=>password.Length>0;
 internal bool Master{get;private set;}internal string Pet{get;private set;}="";internal string Room{get;private set;}="";internal string Error{get;set;}="";internal bool Busy=>work is not null;internal ChatVault? Vault{get;private set;}internal ChatState State{get;private set;}=new();internal List<ChatMessage> Messages{get;}=[];internal bool More{get;private set;}internal string Draft{get;set;}="";internal string TitleDraft{get;set;}="New conversation";internal string Notice{get;set;}="";
 internal void SetAccount(bool master,string pet,string secret){if(Master==master&&Pet==pet&&password==secret&&Vault is not null)return;ResetWork();Master=master;Pet=pet;password=secret;Vault=null;enrolled=false;Room="";Draft="";Messages.Clear();State=new();Preferences=new();Error="";nextPoll=0;}
 private async Task<JsonElement> Request(string op,object data){using var request=new HttpRequestMessage(HttpMethod.Post,ServiceClient.Endpoint(ServiceClient.BaseUrl,Master?"/api/admin/comms":"/api/device/comms"));request.Headers.Authorization=new(Master?"Basic":"Bearer",Master?Convert.ToBase64String(Encoding.UTF8.GetBytes("admin:"+password)):plugin.Configuration.DeviceToken);request.Content=new StringContent(JsonSerializer.Serialize(new{pet=Master?Pet:null,op,data},ServiceClient.Json),Encoding.UTF8,"application/json");using var response=await http.SendAsync(request,cancel.Token).ConfigureAwait(false);var bytes=await response.Content.ReadAsByteArrayAsync(cancel.Token).ConfigureAwait(false);if(bytes.Length>16000000)throw new InvalidOperationException("Chat response too large.");using var json=JsonDocument.Parse(bytes);if(!response.IsSuccessStatusCode)throw new InvalidOperationException(json.RootElement.TryGetProperty("code",out var code)?code.GetString():"Chat service unavailable.");return json.RootElement.Clone();}
 internal async Task<byte[]> SoundBytes(string id){using var request=new HttpRequestMessage(HttpMethod.Get,ServiceClient.Endpoint(ServiceClient.BaseUrl,"/api/admin/sound?id="+id));request.Headers.Authorization=new("Basic",Convert.ToBase64String(Encoding.UTF8.GetBytes("admin:"+password)));using var response=await http.SendAsync(request,cancel.Token);response.EnsureSuccessStatusCode();if(response.Content.Headers.ContentLength>2000000)throw new InvalidOperationException();var bytes=await response.Content.ReadAsByteArrayAsync(cancel.Token);if(bytes.Length>2000000)throw new InvalidOperationException();return bytes;}
 internal Task<JsonElement> AudioRequest(string op,object data)=>Request(op,data);
 private void ResetWork(){if(work is not null){_ = work.ContinueWith(t=>{_ = t.Exception;},TaskContinuationOptions.OnlyOnFaulted);work=null;completed=null;}pendingRoom="";}
 private void Start(string op,object data,Action<JsonElement>? after=null){if(Busy||Paused)return;work=Request(op,data);completed=after;pendingRoom=JsonSerializer.SerializeToElement(data,ServiceClient.Json).TryGetProperty("id",out var id)?id.GetString()??"":"";}
 internal void Save(){if(Vault is null)return;vaultSaved=false;var encrypted=PrivateChatCrypto.Store(Vault);if(!plugin.Mutate(c=>c.PrivateChatVaults[vaultKey]=encrypted))throw new InvalidOperationException(plugin.SaveError);vaultSaved=true;}
 internal void Tick(bool visible)
 {
  if(Paused)return;
  if(Vault is not null&&!vaultSaved){if(Environment.TickCount64<nextPoll)return;try{Save();Error="";}catch{Error="Could not save protected chat storage. Sending is paused until saving succeeds.";nextPoll=Environment.TickCount64+5000;return;}}
  if(work is {IsCompleted:true}){var old=work;var finish=completed;var failedRoom=pendingRoom;work=null;completed=null;try{var value=old.GetAwaiter().GetResult();Error="";finish?.Invoke(value);}catch(Exception e){Error=e.Message;nextPoll=Environment.TickCount64+5000;if(Error is "CHAT_RESET" or "CHAT_NOT_FOUND"){if(Vault is not null&&Vault.Outbox.Count>0){Vault.Outbox.RemoveAll(x=>x.Data.TryGetProperty("id",out var id)&&id.GetString()==failedRoom);Save();}Messages.Clear();Draft="";refreshFirst=true;}else if(Error=="CHAT_DEVICE_REQUIRED"){Vault=null;enrolled=false;Room="";Draft="";Messages.Clear();State=new();}else if(Error=="CHAT_PAUSED"){refreshFirst=true;nextPoll=0;}else if(Error=="CHAT_CHANGED"&&Vault is not null){Vault.Outbox.RemoveAll(x=>x.Op=="rename"&&x.Data.TryGetProperty("id",out var id)&&id.GetString()==failedRoom);Notice="Conversation changed on another device. Review its title before renaming again.";Save();refreshFirst=true;nextPoll=0;}}}
  if(Busy||Environment.TickCount64<nextPoll||password.Length==0&&Master||!Master&&!plugin.IsPaired)return;
  if(Vault is null){if(!visible)return;Start("whoami",new{},value=>{var scope=value.GetProperty("petId").GetString()!;vaultKey=(Master?"master:":"pet:")+scope;Vault=plugin.Configuration.PrivateChatVaults.TryGetValue(vaultKey,out var encrypted)?PrivateChatCrypto.Load(encrypted):new(){Scope=scope,Role=Master?"master":"pet",Identity=PrivateChatCrypto.Identity(),Personas=[new(){Name=Master?"Master":"Pet"}]};if(Vault.Scope!=scope||Vault.Role!=(Master?"master":"pet"))throw new InvalidOperationException("Chat identity belongs to another participant.");ApplyEpoch(value.GetProperty("epoch").GetInt32());Preferences=value.GetProperty("preferences").Deserialize<ChatPreferences>(ServiceClient.Json)!;Save();});return;}
  if(!enrolled){if(!visible)return;Start("enroll",new{id=Vault.Identity.Id,publicKey=Vault.Identity.PublicKey,signKey=Vault.Identity.SignKey},_=>{enrolled=true;refreshFirst=true;});return;}
  if(refreshFirst){refreshFirst=false;Poll(false,visible);return;}
  if(Vault.Outbox.FirstOrDefault(x=>x.Op!="message"||!x.Data.TryGetProperty("id",out var id)||!ConversationPaused(id.GetString()??"")) is { } queued){Start(queued.Op,queued.Data,_=>{Vault.Outbox.Remove(queued);Save();nextPoll=0;});return;}
  if(!Focused||Environment.TickCount64<nextPoll)return;Poll(false,visible);
 }
 internal void Poll(bool older,bool transcript=true){if(Busy||Vault is null||!enrolled)return;loadingOlder=older;nextPoll=Environment.TickCount64+(transcript?2000:5000);Start("state",new{deviceId=Vault.Identity.Id,threadId=transcript&&Room.Length>0?Room:null,before=older?Messages.FirstOrDefault()?.Sequence:null,after=!older&&Messages.Count>0?Messages.Last().Sequence:null},value=>{
  var state=JsonSerializer.Deserialize<ChatState>(value,ServiceClient.Json)!;ApplyEpoch(state.Epoch);State=state;Preferences=state.Preferences;
  var arrivals=0;foreach(var t in state.Threads.Where(t=>!t.Deleted)){if(ConversationPaused(t.Id))continue;var had=Vault!.Notified.TryGetValue(t.Id,out var previous);if(had&&ulong.Parse(t.LastPeerSequence)>ulong.Parse(previous!)&&!Preferences.Muted.Contains(t.Id)&&(!transcript||Room!=t.Id))arrivals++;Vault.Notified[t.Id]=t.LastPeerSequence;}if(arrivals>0)Plugin.Notifications.AddNotification(new Dalamud.Interface.ImGuiNotification.Notification{Title="Private RP chat",Content=arrivals==1?"A conversation has a new message.":arrivals+" conversations have new messages.",Type=Dalamud.Interface.ImGuiNotification.NotificationType.Info});
  foreach(var thread in state.Threads){var previous=Vault.Generations.GetValueOrDefault(thread.Id);if(thread.Generation<previous)throw new InvalidOperationException("Conversation rollback detected.");if(thread.Deleted||previous!=0&&previous!=thread.Generation){foreach(var key in Vault.Keys.Keys.Where(k=>k.StartsWith(thread.Id+":",StringComparison.Ordinal)).ToList())Vault.Keys.Remove(key);Vault.Drafts.Remove(thread.Id);Vault.Outbox.RemoveAll(x=>x.Data.TryGetProperty("id",out var id)&&id.GetString()==thread.Id);if(Room==thread.Id){Messages.Clear();Draft="";}}Vault.Generations[thread.Id]=thread.Generation;}
  if(Room.Length>0&&!state.Threads.Any(t=>t.Id==Room&&!t.Deleted)){Room="";Messages.Clear();Draft="";}
  var empty=Messages.Count==0;foreach(var message in state.Messages){var thread=State.Threads.FirstOrDefault(t=>t.Id==Room);if(thread is null||thread.Deleted||message.Generation!=thread.Generation||Messages.Any(m=>m.Id==message.Id))continue;try{message.Content=PrivateChatCrypto.Open<ChatContent>(Key(thread),["message",thread.Id,thread.Generation,message.Id],message.Packet,Trusted(message.Packet.DeviceId));Messages.Add(message);}catch(Exception e){Error=e.Message;}}
  Messages.Sort((a,b)=>ulong.Parse(a.Sequence).CompareTo(ulong.Parse(b.Sequence)));if(loadingOlder||empty)More=state.More;Save();
 });}
 private void ApplyEpoch(int epoch){if(Vault is null)return;if(epoch<Vault.Epoch)throw new InvalidOperationException("Conversation rollback detected.");if(epoch>Vault.Epoch){Vault.Keys.Clear();Vault.Notified.Clear();Vault.Drafts.Clear();Vault.Outbox.Clear();Messages.Clear();Draft="";Room="";Vault.Epoch=epoch;}}
 internal ChatDevice Trusted(string id){var d=State.Devices.FirstOrDefault(d=>d.Id==id)??throw new InvalidOperationException("Unknown device.");if(d.Id!=Vault!.Identity.Id&&Vault.Pins.GetValueOrDefault(d.Id)!=d.PublicKey+"|"+d.SignKey)throw new InvalidOperationException("Compare and approve device fingerprints in Chat Settings.");return d;}
 internal string Key(ChatThread thread){var id=thread.Id+":"+thread.Generation;if(Vault!.Keys.TryGetValue(id,out var key))return key;var envelope=thread.Envelopes.FirstOrDefault(e=>e.RecipientId==Vault.Identity.Id)??throw new InvalidOperationException("An approved device needs to share this conversation with you.");key=PrivateChatCrypto.Unwrap(thread.Id,thread.Generation,envelope,Vault.Identity,Trusted(envelope.DeviceId));Vault.Keys[id]=key;return key;}
 internal string Title(ChatThread thread){try{return PrivateChatCrypto.Open<ChatContent>(Key(thread),["title",thread.Id,thread.Generation],thread.Title,Trusted(thread.Title.DeviceId)).Title??"Conversation";}catch{return "Locked conversation";}}
 internal void Choose(string id){if(Busy||Vault is null)return;StoreDraft();Room=id;Messages.Clear();Draft=Vault.Drafts.GetValueOrDefault(id)??"";More=false;nextPoll=0;}
 internal void StoreDraft(){if(Vault is null||Room.Length==0)return;Vault.Drafts[Room]=Draft;Save();}
 private List<ChatEnvelope> Recipients(string key,string id,int generation)=>State.Devices.Where(d=>d.Id==Vault!.Identity.Id||Vault.Pins.GetValueOrDefault(d.Id)==d.PublicKey+"|"+d.SignKey).Select(d=>PrivateChatCrypto.Wrap(key,id,generation,d,Vault!.Identity)).ToList();
 private JsonElement WithEpoch(object data){var value=JsonSerializer.SerializeToNode(data,ServiceClient.Json)!.AsObject();value["epoch"]=Vault!.Epoch;return JsonSerializer.SerializeToElement(value,ServiceClient.Json);}
 private void Queue(string op,object data){if(Vault is null||Paused)return;Vault.Outbox.Add(new(){Op=op,Data=WithEpoch(data)});Save();nextPoll=0;}
 internal void Create(){if(Busy||Vault is null||string.IsNullOrWhiteSpace(TitleDraft))return;var id=Guid.NewGuid().ToString();var key=PrivateChatCrypto.NewKey();Vault.Keys[id+":1"]=key;Vault.Generations[id]=1;Queue("thread",new{id,deviceId=Vault.Identity.Id,title=PrivateChatCrypto.Seal(key,["title",id,1],new{title=TitleDraft},Vault.Identity),envelopes=Recipients(key,id,1)});Choose(id);}
 internal void Send(){if(Paused||ConversationPaused(Room)||Vault is null||string.IsNullOrWhiteSpace(Draft)||Room.Length==0)return;var thread=State.Threads.First(t=>t.Id==Room&&!t.Deleted);var persona=Vault.Personas.FirstOrDefault(p=>p.Id==Vault.Active)??Vault.Personas.First();var id=Guid.NewGuid().ToString();var packet=PrivateChatCrypto.Seal(Key(thread),["message",Room,thread.Generation,id],new{alias=persona.Name,color=persona.Color,text=Draft},Vault.Identity);Queue("message",new{id=Room,generation=thread.Generation,deviceId=Vault.Identity.Id,messageId=id,packet});Draft="";Vault.Drafts.Remove(Room);Save();Notice="Queued";}
 internal void Rename(){var t=State.Threads.First(x=>x.Id==Room);Queue("rename",new{id=Room,generation=t.Generation,deviceId=Vault!.Identity.Id,revision=t.Revision,title=PrivateChatCrypto.Seal(Key(t),["title",Room,t.Generation],new{title=TitleDraft},Vault.Identity)});}
 internal void Clear(bool delete,bool all=false){if((!Master&&!delete)||Busy||Vault is null)return;if(all){Queue("clearAll",new{id=Guid.NewGuid().ToString()});Messages.Clear();Draft="";return;}var t=State.Threads.First(x=>x.Id==Room);if(delete){Queue("delete",new{id=Room,generation=t.Generation});return;}var name=Title(t);var generation=t.Generation+1;var key=PrivateChatCrypto.NewKey();Queue("clear",new{id=Room,generation=t.Generation,deviceId=Vault.Identity.Id,title=PrivateChatCrypto.Seal(key,["title",Room,generation],new{title=name},Vault.Identity),envelopes=Recipients(key,Room,generation)});Vault.Keys[Room+":"+generation]=key;Messages.Clear();Draft="";Vault.Drafts.Remove(Room);Save();}
 internal void Approve(ChatDevice device){Vault!.Pins[device.Id]=device.PublicKey+"|"+device.SignKey;foreach(var t in State.Threads.Where(t=>!t.Deleted))try{var envelope=PrivateChatCrypto.Wrap(Key(t),t.Id,t.Generation,device,Vault.Identity);Queue("share",new{id=t.Id,generation=t.Generation,deviceId=Vault.Identity.Id,envelopes=new[]{envelope}});}catch{}Save();nextPoll=0;}
 internal void Import(string json,string secret){var restored=PrivateChatCrypto.Restore(json,secret);if(Vault is null||restored.Scope!=Vault.Scope||restored.Role!=Vault.Role)throw new InvalidOperationException("This backup belongs to another participant.");Vault=restored;Save();enrolled=false;Room="";Draft="";Messages.Clear();State=new();}
 internal void Lock(){if(Vault is not null)StoreDraft();ResetWork();password="";Vault=null;State=new();Messages.Clear();Draft="";enrolled=false;}
 public void Dispose(){ResetWork();cancel.Cancel();http.Dispose();cancel.Dispose();password="";Vault=null;}
}
